 * Serializes a request body for use in a Swagger "try it out" request.
 *
 * Swagger UI hands us a variety of body types depending on the operation's
 * media type. We can only proxy plain string / URL-encoded bodies through the
 * Bruno request pipeline, so anything binary or multipart is rejected with a
 * descriptive TypeError telling the user how to proceed.
 */

export const UNSUPPORTED_BODY_TYPE_CODE = 'UNSUPPORTED_BODY_TYPE';

export const UNSUPPORTED_BODY_MESSAGE = (bodyTypeName) =>
  `${bodyTypeName} isn't supported in Bruno yet. Supported body types are JSON, URL-encoded forms, plain text.`;

const unsupportedBodyError = (bodyType, message) => {
  const error = new TypeError(message);
  error.code = UNSUPPORTED_BODY_TYPE_CODE;
  error.bodyType = bodyType;
  return error;
};

/**
 * @param {*} body - the request body provided by Swagger UI
 * @returns {undefined|string} undefined for null/undefined, otherwise a string
 * @throws {TypeError} for unsupported (binary / multipart) body types
 */
const serializeBody = (body) => {
  if (body === null || body === undefined) {
    return undefined;
  }

  if (typeof body === 'string') {
    return body;
  }

  if (typeof URLSearchParams !== 'undefined' && body instanceof URLSearchParams) {
    return body.toString();
  }

  if (typeof FormData !== 'undefined' && body instanceof FormData) {
    throw unsupportedBodyError(
      'FormData',
      `Multipart form data ${UNSUPPORTED_BODY_MESSAGE('FormData')} Create a Bruno request to send multipart form data.`
    );
  }

  if (typeof File !== 'undefined' && body instanceof File) {
    throw unsupportedBodyError('File', `File upload ${UNSUPPORTED_BODY_MESSAGE('File')}`);
  }

  if (typeof Blob !== 'undefined' && body instanceof Blob) {
    throw unsupportedBodyError('Blob', `Binary file upload ${UNSUPPORTED_BODY_MESSAGE('Blob')}`);
  }

  if (typeof ArrayBuffer !== 'undefined' && body instanceof ArrayBuffer) {
    throw unsupportedBodyError('ArrayBuffer', `Binary data ${UNSUPPORTED_BODY_MESSAGE('ArrayBuffer')}`);
  }

  if (typeof ArrayBuffer !== 'undefined' && ArrayBuffer.isView(body)) {
    const bodyType = body.constructor && body.constructor.name ? body.constructor.name : 'TypedArray';
    throw unsupportedBodyError(bodyType, `Binary data ${UNSUPPORTED_BODY_MESSAGE(bodyType)}`);
  }

  const bodyType = body.constructor && body.constructor.name ? body.constructor.name : typeof body;
  throw unsupportedBodyError(bodyType, UNSUPPORTED_BODY_MESSAGE(bodyType));
};

export default serializeBody;
