[metadata] {"type": "create", "filePath": "/workspace/repo/packages/bruno-electron/src/ipc/swagger-fetch.js", "content": "const axios = require('axios');

/**
 * Proxies an HTTP request for the Swagger "try it out" panel through the
 * Electron main process, sidestepping the browser's CORS restrictions.
 *
 * @param {object} [payload]
 * @param {string} payload.url
 * @param {string} [payload.method]
 * @param {object} [payload.headers]
 * @param {string} [payload.body]
 * @returns {Promise<object>} success, HTTP, error, or validation-failure object
 */
const proxySwaggerFetch = async (payload) => {
  if (!payload || !payload.url) {
    return { error: true, code: 'INVALID_REQUEST' };
  }

  const { url, method, headers, body } = payload;

  try {
    const response = await axios({
      url,
      method,
      headers,
      data: body,
      responseType: 'arraybuffer',
      validateStatus: () => true
    });

    let responseHeaders = response.headers;
    if (responseHeaders && typeof responseHeaders.toJSON === 'function') {
      responseHeaders = responseHeaders.toJSON();
    }

    return {
      status: response.status,
      statusText: response.statusText,
      headers: responseHeaders,
      bodyBase64: Buffer.from(response.data).toString('base64')
    };
  } catch (error) {
    return { error: true, code: error.code, message: error.message };
  }
};

module.exports = { proxySwaggerFetch };
